import{_ as a}from"./chunks/c942050f3632721194f7.BjNs8BRl.js";import{_ as r,C as o,o as l,c as s,j as e,a as n,E as h,a5 as i}from"./chunks/framework.DNkHA0lr.js";const w=JSON.parse('{"title":"为什么你赚钱很困难（以及改变现状的7个教训）","description":"","frontmatter":{"title":"为什么你赚钱很困难（以及改变现状的7个教训）","originalTitle":"Why You Struggle To Make Money (and 7 Lessons To Change That)","date":"2022-09-03","originalUrl":"https://thedankoe.com/letters/why-you-struggle-to-make-money-and-7-lessons-to-change-that/","minutes":13,"sourceHash":"a1299723165a7bbe7aa9ad4e6dcd0b61bc913b9fa48f1686c0f65d94b4543388","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/why-you-struggle-to-make-money-and-7-lessons-to-change-that/"}]]},"headers":[],"relativePath":"letters/why-you-struggle-to-make-money-and-7-lessons-to-change-that.md","filePath":"letters/why-you-struggle-to-make-money-and-7-lessons-to-change-that.md"}'),m={name:"letters/why-you-struggle-to-make-money-and-7-lessons-to-change-that.md"};function c(u,p,d,f,b,k){const t=o("ArticleMeta");return l(),s("div",null,[p[0]||(p[0]=e("h1",{id:"为什么你赚钱很困难-以及改变现状的7个教训",tabindex:"-1"},[n("为什么你赚钱很困难（以及改变现状的7个教训） "),e("a",{class:"header-anchor",href:"#为什么你赚钱很困难-以及改变现状的7个教训","aria-label":'Permalink to "为什么你赚钱很困难（以及改变现状的7个教训）"'},"​")],-1)),h(t),p[1]||(p[1]=i('<p><a href="https://www.youtube.com/embed/ijU4OTfzu8Y?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>钱是个大问题。</p><p>大家都心知肚明。</p><p>没人能逃脱追捧最新“暴富”建议的欲望，比如牛股、垃圾币（shitcoins），以及任何承诺能赚快钱的东西。</p><p>它影响着我们生活的方方面面。</p><ul><li>我们能吃到的食物</li><li>我们能居住的环境</li><li>我们能结交的人脉</li><li>某个处境会给我们带来多少压力</li></ul><p>而这些反过来又会形成闭环，从根本上影响我们赚钱的能力。</p><p>更不用说：</p><p>99%的人都不知道什么才是真正可能的。</p><p>从小到大，当我们的大脑还是一张白纸时，就被灌输了各种废话，而我们却把它们当成事实接受了。</p><p>意识到这一点很伤人，但阻碍你赚到你想赚的那么多钱的唯一因素，就是<em>你</em>自己。</p><ul><li>你的思想塑造你的现实。</li><li>你的信念决定你如何看待这些思想。</li><li>你的认知决定你在这个世界上的行动方式。</li></ul><p>如果你根本不相信自己能赚到一百万，那你还会注意到自己正畅游在机会的海洋中吗？还是你的认知会蒙蔽你的双眼，让你对眼前的事物视而不见？</p><p>这些都不容易，但谁说它本来就该容易的？</p><p>我来替你回答，</p><p>是<em>你</em>自己。</p><h2 id="压力社会" tabindex="-1">压力社会 <a class="header-anchor" href="#压力社会" aria-label="Permalink to &quot;压力社会&quot;">​</a></h2><p>是什么导致了压力？</p><p><a href="https://thedankoe.com/why-you-always-feel-overwhelmed/" target="_blank" rel="noreferrer">焦点</a>。</p><p>也就是你注意力放置的地方。你意识里的内容。</p><p>它是分裂且狭隘的吗？分散的吗？极度执着于已经发生的、将要发生的以及没有发生的事情吗？</p><p>还是单一且宽广的？</p><p>你看到的是冰山一角？还是水面之下的全貌？</p><p>生存。这就是水面之下的东西。</p><p>你采取的。每一项。行动都是出于生存的需求。</p><p>不是过去那种肉体上的生存。</p><p>我说的是自我的生存。</p><p>自我是什么？它是一种幻觉。</p><p>我们的大脑起初就是一张白纸。</p><p>随着年龄增长，我们用大脑创造了自我。</p><p>你看，只有当成百上千种外部关系随着时间建立起来时，自我才真正存在。</p><p>“我的名字叫丹（Dan）”，这是我和我遇到的每个人之间的一种关系。</p><p>如果没有其他“自我”存在，我到底为什么要管自己叫“丹”？我为什么需要说某种语言？或者到底为什么要说话？</p><p>如果某种特定的宗教、意识形态、文化规范、期望、观点、信仰、偏见或词语没有进入你的意识，它对你来说还存在吗？</p><p>把自我看作是一堆微小的点，它们组成了一个人的形状。想象这些点都连着线。</p><p>当其中一根线被拨动、被抓住或受到威胁时，会发生什么？</p><p>压力反应。不管有多微小（但会不断累积）。</p><p>我们的注意力被吸回到更紧迫的事情上。即自我的生存。试图阻止一根连接着我们身份认同的线走向灭亡。</p><p>“好吧，丹，故事编得不错老哥。但这跟我赚真金白银有什么关系？？”</p><p>你来告诉我……</p><p><strong>当你遇到赚钱的机会时会发生什么？</strong></p><p>我来告诉你大多数人是怎么做的：</p><ul><li>他们误判了形势</li><li>他们封闭自己的思想，不去探究眼前事物背后的真相</li><li>他们立刻将其贴上“骗局”、不可能或不适合自己的标签</li></ul><p>一根关乎生存的线被拨动，于是他们选择了封闭自己，以保护他们被程序化植入的信念。如果他们对自己赚钱能力的信念受到威胁，那么他们本身也就受到了威胁。</p><p>你觉得这会带来任何好处吗？</p><p>相反，你必须停下来，通过观察去<em>寻求</em>_理解_你接收到的每一个动态信息片段。</p><p>“对啊，这个叫丹的家伙在卖一个《两小时写手》（2 Hour Writer）的课程。”</p><p>两小时？搞笑，你以为你只要工作两小时就可以收工大吉了？</p><p>写作？创造力？你觉得这玩意儿能变现？没人能靠做自己热爱的事情吃饭。还是回去给那个做着自己热爱之事的的老板打工吧！</p><p>（虽然没人直接这么说，但我保证某些在社交媒体上随机潜水的人心里就是这么想的。他们眼巴巴地等着机会去留下一个对他们未来毫无卵用的差评。）</p><p>这说法是有点夸张，但难道你看不出这有多明显吗？人们是如何<em>选择</em>他们想看的东西，在那个点停下，然后用各种预设填补故事剩下的部分。</p><p>再举个例子：</p><p><strong>当你不得不谈论金钱，或者哪怕只是有人提起这个话题时，你会有什么感觉？</strong></p><p>哪根关乎生存的线受到了威胁？</p><p>是不舒服？是会让你生气？还是让你立刻想到周五工资到账后你必须去还的账单？</p><p>深挖一下。考虑一下可能性。批判性地思考。</p><p>金钱能在外部世界买到自由。</p><p>灵性则在内心世界回归自由。</p><p>我们将在不同的视角下再次讨论生存，因为生活当然不仅仅是金钱。</p><p>但对于大多数人来说，金钱可以使他们承受的压力减少大约80%。</p><p>解决你的财务问题，就能为你腾出空间去放松、去发挥创造力，去解决那些通往真正幸福的深层内心问题。</p><p>而且……自给自足的感觉就是很爽，但为什么呢？</p><p>多巴胺，这种追求“更多”的分子，就像犒劳我们那些必须去打猎的祖先一样在犒劳你。</p><p>就像猴子在灯泡亮起（发出将得到食物的信号）时会产生多巴胺反应，而在同一时间直接获得相同的食物却不会产生多巴胺反应一样。</p><p>我们的心理天生就适合创业。</p><p>也就是说，我们的心理设定决定了我们会因为为了生存去狩猎而产生的新奇感、期待感和不可预测性而获得奖赏。这就是你如何以有益的方式将多巴胺作为杠杆来利用的方法。</p><h2 id="_7个能让你赚到比大学学历多-无限-倍的实用金钱教训" tabindex="-1">7个能让你赚到比大学学历多[无限]倍的实用金钱教训 <a class="header-anchor" href="#_7个能让你赚到比大学学历多-无限-倍的实用金钱教训" aria-label="Permalink to &quot;7个能让你赚到比大学学历多[无限]倍的实用金钱教训&quot;">​</a></h2><p>谈论生存的抽象概念很有趣，它们有助于自我理解，但你该如何落实这些教导呢？</p><p>在改善财务状况的过程中，始终在意识里保持对它们的觉察。</p><p>当你学习这些教训时，留意什么时候会有消极的想法、情绪或感觉进入你的意识。去质疑它。</p><h3 id="_1-竞技场里的人" tabindex="-1">1) 竞技场里的人 <a class="header-anchor" href="#_1-竞技场里的人" aria-label="Permalink to &quot;1) 竞技场里的人&quot;">​</a></h3><p>赚钱是一门技能，而不是一种天赋。</p><p>技能是通过练习来精进的。</p><p>你要怎么练习赚钱呢？</p><p>好吧，它不像某项运动，你可以拉上几个哥们儿一起玩，并且依然能达成最终目标：得分。</p><p>在金钱方面，你必须踏入竞技场。</p><p>金钱的交换不是一场战斗，但如果在竞技场的另一边没有一个“对手”（有钱可给的人），你就没有给自己拼搏的机会。</p><p>没人给你钱 = 你的技能在现实世界中毫无用武之地 = 没有钱装进你的口袋。</p><p>钱不会，也不应该凭空出现并落入你的银行账户。你的心理设定就是为了去狩猎。而不是当一只毫不费力就在虚拟香蕉库里收集香蕉的猴子。</p><p>这就是为什么这么多人都有财务问题。他们喜欢谈论金钱，特别是从负面的角度，但到了要赚更多钱的时候呢？鸦雀无声。因为这意味着他们必须做一些不舒服的事情。看台上的批评声总是最响亮的。嘘——！</p><p><em>学习教你如何赚钱的课程并不是在赚钱。</em></p><p><em>为了赚钱去开发产品、建网站或做App，这也不是在赚钱。</em></p><blockquote><p>学会销售。学会构建。如果你两样都会，你将势不可挡。</p><p>— 纳瓦尔（Naval） (@naval) <a href="https://twitter.com/naval/status/1002104154737684480?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">2018年5月31日</a></p></blockquote><p>你必须去构建，<em>且去销售。</em></p><h3 id="_2-敞开你的心扉" tabindex="-1">2) 敞开你的心扉 <a class="header-anchor" href="#_2-敞开你的心扉" aria-label="Permalink to &quot;2) 敞开你的心扉&quot;">​</a></h3><p>人们之所以沦为金钱的奴隶，是因为他们认为自己没有能力赚得更多。</p><p><em>“我没上过大学，我找不到高薪工作。”</em></p><p><em>“写作？你难道不需要像诗人一样才能写吗？”</em></p><p><em>“哈哈哈你觉得那家伙这个月</em><em><strong>真的</strong></em><em>赚了10万美元吗？利润能有多少？不管怎样，我都认为那是……骗局！”</em></p><p>人们会给自己灌输自我设限的故事，这些故事会狭隘他们的认知，以至于对摆在眼前的无限机会（比如你的手机）视而不见。贫穷变成了他们的现实，而他们的行动也会跟着现实走。</p><h3 id="_3-基础为王" tabindex="-1">3) 基础为王 <a class="header-anchor" href="#_3-基础为王" aria-label="Permalink to &quot;3) 基础为王&quot;">​</a></h3><p><img src="'+a+'" alt=""></p><p>在商业中，你需要两样东西：</p><ol><li><strong>价值</strong>：一个能承诺带来理想结果（并且能兑现承诺）的产品或服务。</li><li><strong>人</strong>：这很明显，但往往被一掠而过。如果你想把你的价值换成金钱，你需要有人能看到你所提供的价值。</li></ol><p>就像约会一样。</p><p>如果你很有价值，很引人注目，也能兑现你展现出的价值，但却没有处在一个有充足人群的环境中……你怎么能指望约到人呢？</p><p>如果你身处一个有充足人群的环境中（不管是物理的还是数字的），但你自己不是一个有价值的人……结果还是一样。</p><p>如果你把这些基础原则应用到网络环境中，人就来自于媒体，就像你现在正在阅读的这个媒体一样。</p><p>媒体是互联网的前端。正是它在捕获、留存并在注意力上交付价值。</p><p>写作、演讲、视频、音频、设计。</p><p>我更喜欢写作，因为它能帮你在将信息重新用于其他媒介之前，先对其进行提炼。就像这封信将会被当做一份轻度的YouTube脚本来使用一样。</p><p>如果你想学习一项数字经济中常青的技能，并实践我的内容生态系统，去看看《<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">两小时写手</a>》（The 2 Hour Writer）。</p><p>媒体会吸引<em>人</em>，但你该如何创造、展示并推广你所能提供的<em>价值</em>呢？</p><p>营销、销售、影响力、说服力，以及使用无代码工具进行构建。</p><p>通过学习一项能帮你在任一领域（人或价值）取得成功的技能，你的各项技能将产生交叉并相互补充。特别是当你在网络的“竞技场”中拥有个人品牌时。</p><p>再说回“敞开你的心扉”，技能获取正是辅助做到这一点的一种方式。</p><h3 id="_4-一人企业" tabindex="-1">4) 一人企业 <a class="header-anchor" href="#_4-一人企业" aria-label="Permalink to &quot;4) 一人企业&quot;">​</a></h3><p>互联网在可能性的范围上拉平了竞争的起跑线。</p><blockquote><p>过去需要：\\</p><p>– 几千块钱<br> – 一整个员工团队<br> – 多年的学习和实践\\</p><p>现在用一款免费软件就能搞定。\\</p><p>你可以极度专注地去开发一套高价值的技能，以此利用这些工具作为杠杆。\\</p><p>这话听着老套，但现在面临的机会真的是前所未有的高。</p><p>— 丹·科（DAN KOE） (@thedankoe) <a href="https://twitter.com/thedankoe/status/1565631122825945089?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">2022年9月2日</a></p></blockquote><p>一人企业的核心就是最大化你的时间自由，做你真正享受的事，并在做的过程中赚到绰绰有余的钱。</p><p>我相信这对99%的人来说都是最好的选择。而不是梦想着要创办一家价值十亿美元的巨头公司，然后啥行动也没有。</p><p>这关乎于迈出小步、个人成长，以及提供尽可能多的由<em>你</em>能创造的价值。</p><p>具体做法如下：</p><p><strong>开启一门服务业务。</strong></p><blockquote><p>研究你的兴趣<br> 开启服务型业务<br> 增长受众<br> 免费工作<br> 开发你的流程<br> 提高价格<br> 重复第5-6步<br> 将你的流程产品化\\</p><p>这需要2年时间，以实现潜在的每月5万美元以上收入和每天3小时工作时间\\</p><p>上大学需要4年时间，以实现潜在的每月1万美元收入和每天9小时工作时间</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1480875904104599553?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">2022年1月11日</a></p></blockquote><p>如果你无法利用金钱或受众杠杆来将<em>人</em>吸引到产品上。那就从服务开始。</p><p>为什么？</p><p>因为你可以发送冷邮件、陌生私信，或者制定策略，在社交媒体上出现在更多人面前。</p><p>而且，因为通过直接回应营销、销售和适当的冷拓客策略，推销更昂贵的服务反而更容易（没错，就是更容易）。</p><p>那么，你能否通过在私信中推销低价<em>产品</em>，在几个月内为自己创造收入呢？</p><p>答案是不能，你需要更多的资金、成果和权威，才能通过你的品牌去销售产品。</p><p>但只要策略得当，仅凭私信和邮件，你就能拿下4个以上价值2500美元的客户。</p><p><strong>同时建立受众群体。</strong></p><p>你肯定不想一辈子都在发陌生私信。以受众的形式建立杠杆才是明智之举。</p><p>你该聊些什么？与你所售服务相关的可执行建议。</p><p><em>如果你销售健康教练服务，那就聊健康。</em></p><p><em>如果你销售营销服务，那就聊营销。</em></p><p><em>如果你销售会计服务，那就聊钱。</em></p><p>这将确立你的权威，让你进入成千上万人的视线，并扩展你的网络。</p><p>想想看，你不仅可以直接接触到你的受众，<em>你还可以间接接触到关注你的那些人背后的所有受众</em>_._</p><p>花点时间想一想。这其实非常疯狂。</p><p><strong>一旦取得成果，就开始产品化。</strong></p><p>既然我们已经为客户取得了成果，并通过谈论我们的专业知识建立了一批受众，那么现在是时候产品化了。</p><p>创造一款产品，其中包含你在服务型业务中日常采取的确切系统和行动。</p><p>在发布产品时，你可以使用客户的评价作为最初的社会认同。</p><p>这封信已经很长了，所以我打算把一人企业的内容完全留到另一封信里讲。</p><p><em>如果你想要180多种建立一人企业（以及高绩效思维）的策略、培训和循序渐进的路线图，请查看Modern Mastery（现代精通）。<a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">读者可以花5美元加入。</a></em></p><h3 id="_5-大处着眼-小处着手" tabindex="-1">5) 大处着眼，小处着手 <a class="header-anchor" href="#_5-大处着眼-小处着手" aria-label="Permalink to &quot;5) 大处着眼，小处着手&quot;">​</a></h3><blockquote><p>迷茫时，尝试一切，看看什么能奏效。\\</p><p>感到不堪重负时，放下一切，看看什么留得住。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1565268731017699328?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">2022年9月1日</a></p></blockquote><p>敞开心扉，接纳变富的潜能，是变富的第一步。</p><p>财富要求创造力与生产力之间达到平衡。</p><p>创造力需要开放的心态和元视角。</p><p>生产力需要清晰的头脑和高度集中的注意力。</p><p>创造力就像你漂浮在太空中。星星就是进入你意识的想法。当你创造出星座，也就是星星之间的连接时，能盈利的解决方案就诞生了。</p><p>生产力就像你乘坐火箭飞向月球。不需要任何思考。一切都是经过计算、计划和万无一失的。你划破长空，以创纪录的时间抵达目的地……因为结果早已注定。</p><p>创造力关乎连接，生产力关乎清晰。</p><p>为这两者安排专门的时间。</p><p>你可以使用我的<a href="https://thedankoe.com/the-3-part-daily-routine-for-maximum-productivity/" target="_blank" rel="noreferrer">填补-留白-使用（Fill Empty Use）</a>框架来找到属于你自己的平衡。</p><h3 id="_6-提高基础收入-维持基础生活方式" tabindex="-1">6) 提高基础收入，维持基础生活方式 <a class="header-anchor" href="#_6-提高基础收入-维持基础生活方式" aria-label="Permalink to &quot;6) 提高基础收入，维持基础生活方式&quot;">​</a></h3><p>在单人创业中，一切都是不可预测的。（这是件好事）</p><p>当然，你可以创建一个会员制或其他每月循环的付费项目来创造一定的稳定性……但关键是，你的收入总会有高潮和低谷的月份。</p><p>上周，我实现了第一个月入10万美元的目标。</p><p>除非我积极争取，否则我这个月是达不到那个数字的，但我需要休息。</p><p>话虽如此，达到10万美元意味着我的基准线提高了。</p><p>这似乎总是发生在一顿战术性施压之后。</p><blockquote><p>战术性施压：\\</p><p>有意识地决定将自己置于背水一战的境地——清楚自己有能力让其奏效——并且除了成功不接受任何其他结果。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1525117916538097666?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">2022年5月13日</a></p></blockquote><p>我会强迫自己发布一款产品或搞一次促销活动，将其公之于众，而且必须完成，否则我就会在公众面前颜面扫地。</p><p>我每年都会这么做一次，我把自己的大部分成长归功于此。大多数人陷入了空想，从未发布过他们一直在构建的项目。</p><p>话虽如此，生活方式蔓延确确实实是个问题。</p><p>你的月收入会达到一个高点，高到你以前做梦都想不到，然后你会通过买个大件来庆祝。</p><p>意思是，你提高了对基础生活方式的需求。</p><p>更多的物品 = 更多的责任 = 占用更多的资源 = 投入业务的资源变少 = 月收入降低 = 难以维持那种生活方式。</p><p>如果你对生活方式的要求随着收入的增加而增加，你的日子就不会好过。</p><h3 id="_7-先利用你的时间杠杆-再利用你的心智杠杆" tabindex="-1">7) 先利用你的时间杠杆，再利用你的心智杠杆 <a class="header-anchor" href="#_7-先利用你的时间杠杆-再利用你的心智杠杆" aria-label="Permalink to &quot;7) 先利用你的时间杠杆，再利用你的心智杠杆&quot;">​</a></h3><blockquote><p>用你的头脑赚钱，而不是用你的时间赚钱。</p><p>— Naval (@naval) <a href="https://twitter.com/naval/status/1206967499838803968?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">2019年12月17日</a></p></blockquote><p>体力劳动意味着你的工作量是有上限的，这也就意味着你的收入是有上限的。</p><p>世界上收入最高的人是那些战略家、梦想家和创新者。</p><p>是的，即使他们没有创立一家价值十亿美元的公司。</p><p>一个年收入百万美元的一人企业需要创造力、杠杆和产品化。</p><p>我的目标是把产品和数字资产部署到位，直到我能把全部的时间都花在写作上。无代码工具、自动化和社交媒体会处理其余的事情。</p><p>除非你有充足的现金流投资于受众增长或流量获取（人），否则你就必须花时间去建立一个服务型业务来获取现金流。</p><p>一旦你通过受众增长建立了数字杠杆，用你的服务取得了成果，并准备好进行产品化……真正的乐趣才刚刚开始。</p><p>大多数人都陷入了饱一顿饥一顿的客户业务中，因为他们没有动脑子。他们没有意识到数字杠杆的价值，没有成长，把时间耗费在发陌生私信和冷邮件的无休止循环中。</p><p>建立受众群体。建立电子邮件列表。建立买家列表。</p><blockquote><p>先建立分发渠道，然后再做你想做的任何东西。</p><p>— Jack Butcher (@jackbutcher) <a href="https://twitter.com/jackbutcher/status/1395945544430854144?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">2021年5月22日</a></p></blockquote><p>那就是数字杠杆。一旦它们足够庞大，你就可以随心所欲地去构建任何东西。</p><p>这封信的内容就到这里。</p><p>如果你喜欢这封信，你也会喜欢本周在表面社交媒体之外发生的事情（见下文）。</p><p>Dan Koe</p><p><strong>本周动态</strong></p><p>我们仍在收到大量关于《2小时写手》的惊人反馈。人们正通过写作（是的，你没看错）在Instagram短视频和TikTok上获得增长，撰写建立权威的优质Newsletter，并拥有一个内容生态系统，让你从海量的新手创作者中脱颖而出。</p><p><a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">点击这里查看2HW（2小时写手）。</a></p><p>在Modern Mastery（现代精通）内部，我们举办了一场品牌研讨会。我们拆解了Based Realists的个人主页，分享了一些为了获取最多粉丝的个人主页设计知识，并回答了大家的问题。</p><p>Joey发布了《创作者技术栈》，详细介绍了启动一人创作者业务（如果你正想涉足这个领域）的最佳软件。</p><p><a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">读者可以点击这里花5美元获取以上两项（甚至更多）内容的访问权限。</a></p><p>和往常一样，YouTube视频稍后会上线。播客也很快就会重新开启。如果你感兴趣，敬请关注。</p><hr><p><a href="/en/letters/why-you-struggle-to-make-money-and-7-lessons-to-change-that">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',188))])}const y=r(m,[["render",c]]);export{w as __pageData,y as default};
